import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.nextLine().trim());
        Map<String, Set<String>> operations = new TreeMap<>();
        for (int i = 0; i < n; i++) {
            String[] parts = sc.nextLine().trim().split("\\s+");
            operations.computeIfAbsent(parts[1], key -> new LinkedHashSet<>()).add(parts[2]);
        }

        List<String> problems = new ArrayList<>();
        for (Map.Entry<String, Set<String>> entry : operations.entrySet()) {
            if (!entry.getValue().contains("C")) {
                problems.add("NOCREATE " + entry.getKey());
            }
            if (!entry.getValue().contains("R")) {
                problems.add("NOREAD " + entry.getKey());
            }
        }

        System.out.println(problems.isEmpty() ? "OK" : "NG");
        problems.forEach(System.out::println);
        System.out.println("データ " + operations.size());
    }
}

