import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        Map<String, String[]> before = read(sc);
        Map<String, String[]> after = read(sc);

        List<String> problems = new ArrayList<>();
        for (Map.Entry<String, String[]> entry : before.entrySet()) {
            String field = entry.getKey();
            String type = entry.getValue()[0];
            boolean wasRequired = entry.getValue()[1].equals("required");
            String[] now = after.get(field);
            if (now == null) {
                if (wasRequired) {
                    problems.add("REMOVED " + field);
                }
                continue;
            }
            if (wasRequired && now[1].equals("optional")) {
                problems.add("WEAKENED " + field);
            }
            if (!type.equals(now[0])) {
                problems.add("TYPECHANGED " + field + " " + type + " " + now[0]);
            }
        }

        int added = 0;
        for (String field : after.keySet()) {
            if (!before.containsKey(field)) {
                added++;
            }
        }

        System.out.println(problems.isEmpty() ? "互換" : "非互換");
        problems.forEach(System.out::println);
        System.out.println("追加 " + added);
    }

    /** 1つの契約を「項目名 -> {型, required/optional}」で読み取る。 */
    static Map<String, String[]> read(Scanner sc) {
        int n = Integer.parseInt(sc.nextLine().trim());
        Map<String, String[]> spec = new TreeMap<>();
        for (int i = 0; i < n; i++) {
            String[] parts = sc.nextLine().trim().split("\\s+");
            spec.put(parts[0], new String[] {parts[1], parts[2]});
        }
        return spec;
    }
}
